// Memory keeps the original layout: every property reads/writes the original address with the same width and
// signedness the original code used (e.g. sprite(choppers, i).state is R32/W32 at choppers + i*SPRITE.SIZE +
// SPRITE.state). Views are cached per address.
import { R16, R32, R8, RF64, W16, W32, W8, WF64 } from '../runtime/mem.js';
