// An object whose properties read/write memory: props = { name: [offset, read, write] } relative to a.
function view(a, props) {
  const o = { addr: a };
  for (const [name, [off, read, write]] of Object.entries(props)) {
    const p = a + off;
    Object.defineProperty(o, name, { get: () => read(p), set: (v) => write(p, v), enumerable: true });
  }
  return o;
}

const SPRITE_PROPS = {
  x: [SPRITE.x, R32, W32],
  y: [SPRITE.y, R32, W32],
  currFrame: [SPRITE.currFrame, R32, W32],
  threshold1: [SPRITE.threshold1, R32, W32],
  threshold2: [SPRITE.threshold2, R32, W32],
  width: [SPRITE.width, R32, W32],
  height: [SPRITE.height, R32, W32],
  visible: [SPRITE.visible, R32, W32],
  state: [SPRITE.state, R32, W32],
  counter2: [SPRITE.counter2, R32, W32],
  counter1: [SPRITE.counter1, R32, W32],
  counter3: [SPRITE.counter3, R32, W32],
  threshold3: [SPRITE.threshold3, R32, W32],
  numFrames: [SPRITE.numFrames, R32, W32],
};
const spriteViews = new Map();
export function sprite(base, i = 0) {
  const a = base + i * SPRITE.SIZE;
  return spriteViews.get(a) ?? spriteViews.set(a, view(a, SPRITE_PROPS)).get(a);
}

